{"code": "import os
from PIL import Image

def check_images_in_directory(directory):
    """Check all image files in a directory for readability."""
    issues = []
    if os.path.exists(directory):
        for root, dirs, files in os.walk(directory):
            for file in files:
                file_path = os.path.join(root, file)
                if file.lower().endswith(('.png', '.jpg', '.jpeg', '.bmp', '.gif')):
                    try:
                        with Image.open(file_path) as img:
                            img.verify()
                    except Exception as e:
                        issues.append((file_path, str(e)))
    return issues

train_issues = check_images_in_directory('data_small/training_set')
test_issues = check_images_in_directory('data_small/test_set')

print("Issues in training set:", train_issues)
print("Issues in test set:", test_issues)"}

